-- Gate devices, guard PINs and gate shift sessions (ADR-0017). Generated by prisma migrate diff, then
-- hand-written grants, RLS and checks. Expand only: existing sessions become kind 'personal'.
-- AlterTable
ALTER TABLE "platform"."sessions" ADD COLUMN     "gate_device_id" UUID,
ADD COLUMN     "kind" TEXT NOT NULL DEFAULT 'personal',
ADD COLUMN     "scope_estate_id" UUID;

-- AlterTable
ALTER TABLE "tenant"."gate_events" ADD COLUMN     "offline_signin" BOOLEAN NOT NULL DEFAULT false;

-- CreateTable
CREATE TABLE "tenant"."gate_devices" (
    "id" UUID NOT NULL,
    "estate_id" UUID NOT NULL,
    "gate_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "credential_hash" TEXT NOT NULL,
    "registered_by" UUID NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'active',
    "last_seen_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "revoked_at" TIMESTAMPTZ(3),
    "revoked_by" UUID,

    CONSTRAINT "gate_devices_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "tenant"."guard_pins" (
    "id" UUID NOT NULL,
    "estate_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "pin_hash" TEXT NOT NULL,
    "failed_attempts" INTEGER NOT NULL DEFAULT 0,
    "locked_at" TIMESTAMPTZ(3),
    "set_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "guard_pins_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "gate_devices_estate_id_status_idx" ON "tenant"."gate_devices"("estate_id", "status");

-- CreateIndex
CREATE UNIQUE INDEX "guard_pins_estate_id_user_id_key" ON "tenant"."guard_pins"("estate_id", "user_id");


-- Hand-written: grants, row-level security and checks. Devices are revoked, never deleted.
GRANT SELECT, INSERT, UPDATE ON "tenant"."gate_devices" TO safezone_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON "tenant"."guard_pins" TO safezone_app;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['gate_devices','guard_pins'] LOOP
    EXECUTE format('ALTER TABLE "tenant".%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE "tenant".%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($p$CREATE POLICY %I ON "tenant".%I FOR ALL TO safezone_app
      USING (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid)
      WITH CHECK (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid)$p$, t || '_tenant', t);
  END LOOP;
END $$;
ALTER TABLE "tenant"."gate_devices" ADD CONSTRAINT gate_devices_status_check
  CHECK (status IN ('active','revoked'));
ALTER TABLE "tenant"."guard_pins" ADD CONSTRAINT guard_pins_attempts_check CHECK (failed_attempts >= 0);
ALTER TABLE "platform"."sessions" ADD CONSTRAINT sessions_kind_check CHECK (kind IN ('personal','gate_shift'));
ALTER TABLE "platform"."sessions" ADD CONSTRAINT sessions_gate_scope_check
  CHECK (kind = 'personal' OR (gate_device_id IS NOT NULL AND scope_estate_id IS NOT NULL));
